def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    def swap_case(letter):
        if letter.islower():
            return letter.upper()
        else:
            return letter.lower()

    def replace_vowel_with_two_places_ahead(vowel):
        vowels = 'aeiouAEIOU'
        for i, v in enumerate(vowels):
            if v == vowel:
                return vowels[(i + 2) % len(vowels)]
        return vowel

    encoded_message = ''
    for char in message:
        if char.isalpha():
            encoded_char = swap_case(char)
            if encoded_char in 'aeiouAEIOU':
                encoded_char = replace_vowel_with_two_places_ahead(encoded_char)
            encoded_message += encoded_char
        else:
            encoded_message += char
    return encoded_message

